package org.example.board.auth;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.example.board.common.ApiException;
import org.example.board.common.ErrorCode;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpMethod;
import org.springframework.stereotype.Component;
import org.springframework.web.cors.CorsUtils;
import org.springframework.web.servlet.HandlerInterceptor;

// /api/** 의 토큰을 한곳에서 확인한다 — 컨트롤러에 들어가기 전이라 본문 검증보다 먼저 401이 난다
@Component
public class AuthInterceptor implements HandlerInterceptor {

    public static final String USER_ID_ATTRIBUTE = "loginUserId";
    private static final String BEARER_PREFIX = "Bearer ";

    private final JwtProvider jwtProvider;

    public AuthInterceptor(JwtProvider jwtProvider) {
        this.jwtProvider = jwtProvider;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        // 브라우저의 CORS 사전 요청(OPTIONS)은 토큰 없이 온다 — 막으면 실행 칸 전체가 CORS로 실패한다
        if (CorsUtils.isPreFlightRequest(request)) {
            return true;
        }
        String header = request.getHeader(HttpHeaders.AUTHORIZATION);
        if (header == null) {
            // 조회(GET)는 비로그인도 된다. 쓰기는 토큰이 있어야 한다
            if (HttpMethod.GET.matches(request.getMethod())) {
                return true;
            }
            throw new ApiException(ErrorCode.UNAUTHORIZED);
        }
        if (!header.startsWith(BEARER_PREFIX)) {
            throw new ApiException(ErrorCode.UNAUTHORIZED, "Authorization 헤더는 'Bearer <토큰>' 형식이어야 합니다.");
        }
        Long userId = jwtProvider.parseUserId(header.substring(BEARER_PREFIX.length()).trim());
        request.setAttribute(USER_ID_ATTRIBUTE, userId);
        return true;
    }
}

